CREATE TABLE ai_rag_trace(id BIGINT NOT NULL,message_id BIGINT NOT NULL,query_digest CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,retrieval_evidence_json JSON NOT NULL,prompt_config_id BIGINT NULL,prompt_version BIGINT UNSIGNED NULL,model_name VARCHAR(128) NOT NULL,retrieval_duration_ms BIGINT UNSIGNED NOT NULL,model_duration_ms BIGINT UNSIGNED NOT NULL,prompt_tokens_estimated INT UNSIGNED NOT NULL,completion_tokens_estimated INT UNSIGNED NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),UNIQUE KEY uk_ai_rag_trace_message(message_id),INDEX idx_ai_rag_trace_created(created_at),CONSTRAINT fk_ai_rag_trace_message FOREIGN KEY(message_id) REFERENCES ai_message(id) ON DELETE CASCADE);
